const input = String($json.body?.chatInput || '').trim();

const normalize = (value) => value
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();

const text = normalize(input);
const hasAny = (words) => words.some((word) => text.includes(word));

let output = '';

if (!text || text.length < 2) {
  output = '__HELP__';
} else if (hasAny(['venta', 'vendimos', 'vendido', 'facturacion', 'boleta', 'ingreso por venta', 'historial de venta'])) {
  output = '__SALES__';
} else if (hasAny(['caja', 'finanza', 'ganancia', 'utilidad', 'egreso', 'ingreso', 'cuentas por cobrar', 'flujo de caja'])) {
  output = '__FINANCE__';
} else if (hasAny(['cliente', 'crm', 'deudor', 'premium', 'frecuente', 'cartera'])) {
  output = '__CLIENTS__';
} else if (hasAny(['compra', 'proveedor', 'pedido', 'abastecimiento', 'recepcion'])) {
  output = '__PURCHASES__';
} else if (hasAny(['produccion', 'fabrica', 'torneria', 'orden de produccion', 'lote'])) {
  output = '__PRODUCTION__';
} else if (hasAny(['empleado', 'personal', 'operario', 'vendedor', 'turno'])) {
  output = '__EMPLOYEES__';
} else if (hasAny(['usuario', 'rol', 'permiso', 'acceso'])) {
  output = '__USERS__';
} else if (hasAny(['dashboard', 'panel', 'kpi', 'indicador', 'estado general', 'situacion actual', 'resumen del sistema'])) {
  output = '__DASHBOARD__';
} else if (hasAny(['stock bajo', 'stock critico', 'por agotarse', 'agotarse', 'critico', 'alerta'])) {
  output = '__INVENTORY_LOW__';
} else if (hasAny(['que repuestos tenemos', 'cuantos repuestos', 'inventario general', 'catalogo', 'productos disponibles', 'lista de productos', 'que inventario', 'repuestos tenemos', 'stock general'])) {
  output = '__ALL__';
} else if (/^(hola|buenas|buen dia|buenas tardes|buenas noches|como estas|que tal|gracias|ok|dale|chau|adios)\b/.test(text)) {
  output = '__CHAT__';
} else if (hasAny(['que puedes hacer', 'ayuda', 'no entiendo', 'como te uso', 'que te puedo preguntar'])) {
  output = '__HELP__';
} else {
  const stop = new Set([
    'tienes', 'tenes', 'hay', 'precio', 'donde', 'esta', 'ubicacion',
    'stock', 'repuesto', 'repuestos', 'para', 'del', 'de', 'la', 'el',
    'los', 'las', 'un', 'una', 'que', 'cual', 'cuanto', 'cuantos',
    'compatible', 'compatibles'
  ]);

  const terms = text
    .replace(/[^a-z0-9+.-]+/g, ' ')
    .split(/\s+/)
    .filter((term) => term.length >= 2 && !stop.has(term))
    .slice(0, 6);

  output = terms.length ? terms.join(' ') : '__HELP__';
}

return [{
  json: {
    text: output,
    originalInput: input
  }
}];

const items = $input.all();
const repuestos = [];
let totalProductos = 0;
let totalUnidades = 0;
const pregunta = $('Webhook').item.json.body.chatInput || '';
const consulta = String($('Extractor de Palabras Clave').item.json.text || $('Extractor de Palabras Clave').item.json.output || '').trim();

for (const item of items) {
  if (Array.isArray(item.json)) {
    repuestos.push(...item.json);
  } else if (Array.isArray(item.json?.repuestos)) {
    repuestos.push(...item.json.repuestos);
    totalProductos = Number(item.json.totalProductos || 0);
    totalUnidades = Number(item.json.totalUnidades || 0);
  } else if (item.json && Object.keys(item.json).length > 0 && !item.json.repuestos) {
    repuestos.push(item.json);
  }
}

const consultaNormalizada = consulta.toUpperCase();
const mapa = {
  '__CHAT__': 'chat',
  '__HELP__': 'ayuda',
  '__DASHBOARD__': 'dashboard',
  '__ALL__': 'inventario_general',
  '__INVENTORY_ALL__': 'inventario_general',
  '__INVENTORY_LOW__': 'inventario_bajo',
  '__SALES__': 'ventas',
  '__FINANCE__': 'finanzas',
  '__CLIENTS__': 'clientes',
  '__PURCHASES__': 'compras',
  '__PRODUCTION__': 'produccion',
  '__EMPLOYEES__': 'empleados',
  '__USERS__': 'usuarios'
};
const tipoConsulta = mapa[consultaNormalizada] || 'busqueda_especifica';

return [{
  json: {
    pregunta,
    consulta,
    tipoConsulta,
    repuestos,
    totalProductos,
    totalUnidades
  }
}];

const item = $input.first().json;
const output = item.text || item.output || item.response || 'No pude generar una respuesta en este momento.';

return [{
  json: {
    output
  }
}];
